/**
 * Domain Entity: CreateSupplier
 *
 * Validates payload for creating a supplier. The `code` is generated by the
 * use case (SUP-### scoped per company), not supplied by the client.
 *
 * `defaultPaymentTermId` is OPTIONAL. Empty string is normalised to null so a
 * cleared form field never triggers payment-term validation.
 */
export class CreateSupplier {
  public readonly name: string;
  public readonly address: string | null;
  public readonly phone: string | null;
  public readonly picName: string | null;
  public readonly defaultPaymentTermId: string | null;

  constructor(payload: unknown) {
    this._verifyPayload(payload);

    const { name, address, phone, picName, defaultPaymentTermId } = payload as Record<
      string,
      unknown
    >;

    this.name = (name as string).trim();
    this.address = address ? (address as string).trim() : null;
    this.phone = phone ? (phone as string).trim() : null;
    this.picName = picName ? (picName as string).trim() : null;
    this.defaultPaymentTermId = this._normaliseId(defaultPaymentTermId);
  }

  private _normaliseId(value: unknown): string | null {
    if (value === undefined || value === null) return null;
    const trimmed = (value as string).trim();
    return trimmed.length === 0 ? null : trimmed;
  }

  private _verifyPayload(payload: unknown): void {
    if (!payload || typeof payload !== 'object') {
      throw new Error('CREATE_SUPPLIER.NOT_CONTAIN_NEEDED_PROPERTY');
    }

    const { name, address, phone, picName, defaultPaymentTermId } = payload as Record<
      string,
      unknown
    >;

    if (!name) {
      throw new Error('CREATE_SUPPLIER.NOT_CONTAIN_NEEDED_PROPERTY');
    }

    if (typeof name !== 'string') {
      throw new Error('CREATE_SUPPLIER.NOT_MEET_DATA_TYPE_SPECIFICATION');
    }
    if (address !== undefined && address !== null && typeof address !== 'string') {
      throw new Error('CREATE_SUPPLIER.NOT_MEET_DATA_TYPE_SPECIFICATION');
    }
    if (phone !== undefined && phone !== null && typeof phone !== 'string') {
      throw new Error('CREATE_SUPPLIER.NOT_MEET_DATA_TYPE_SPECIFICATION');
    }
    if (picName !== undefined && picName !== null && typeof picName !== 'string') {
      throw new Error('CREATE_SUPPLIER.NOT_MEET_DATA_TYPE_SPECIFICATION');
    }
    if (
      defaultPaymentTermId !== undefined &&
      defaultPaymentTermId !== null &&
      typeof defaultPaymentTermId !== 'string'
    ) {
      throw new Error('CREATE_SUPPLIER.NOT_MEET_DATA_TYPE_SPECIFICATION');
    }

    if (name.trim().length === 0 || name.trim().length > 100) {
      throw new Error('CREATE_SUPPLIER.NAME_LIMIT_CHAR');
    }
    if (phone && (phone as string).trim().length > 30) {
      throw new Error('CREATE_SUPPLIER.PHONE_LIMIT_CHAR');
    }
    if (picName && (picName as string).trim().length > 100) {
      throw new Error('CREATE_SUPPLIER.PIC_NAME_LIMIT_CHAR');
    }
  }
}
